def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Initialize grid values
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Use a 4D DP table to store the maximum value collected by two paths
    # dp[i1][j1][i2] represents the maximum value collected when one path is at (i1, j1)
    # and the other path is at (i2, j2) where j2 = i1 + j1 - i2
    dp = [[[-1] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    dp[0][0][0] = grid[0][0]

    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(N):
                j2 = i1 + j1 - i2
                if j2 < 0 or j2 >= N or grid[i1][j1] == 0 or grid[i2][j2] == 0:
                    dp[i1 + 1][j1][i2 + 1] = -1
                    continue
                max_value = -1
                for di1, dj1 in [(-1, 0), (0, -1)]:
                    for di2, dj2 in [(-1, 0), (0, -1)]:
                        pi1, pj1 = i1 + di1, j1 + dj1
                        pi2, pj2 = i2 + di2, j2 + dj2
                        if 0 <= pi1 < N and 0 <= pj1 < N and 0 <= pi2 < N and 0 <= pj2 < N:
                            if dp[pi1][pj1][pi2] != -1:
                                value = dp[pi1][pj1][pi2]
                                if (i1, j1) == (i2, j2):
                                    value += grid[i1][j1]
                                else:
                                    value += grid[i1][j1] + grid[i2][j2]
                                max_value = max(max_value, value)
                dp[i1 + 1][j1][i2 + 1] = max_value

    return max(0, dp[N - 1][N - 1][N - 1])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from functools import lru_cache

    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    @lru_cache(None)
    def dp(r1, c1, c2):
        r2 = r1 + c1 - c2
        if r1 >= N or r2 >= N or c1 >= N or c2 >= N or grid[r1][c1] == -1 or grid[r2][c2] == -1:
            return float('-inf')
        if r1 == c1 == N - 1:
            return grid[r1][c1]

        ans = grid[r1][c1] + (grid[r2][c2] if c1 != c2 else 0)
        ans += max(dp(r1 + 1, c1, c2), dp(r1 + 1, c1, c2 + 1),
                   dp(r1, c1 + 1, c2), dp(r1, c1 + 1, c2 + 1))

        return ans

    return max(0, dp(0, 0, 0))

