def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def count_separated_pairs(horizontal_aisle, vertical_aisle):
        separated_count = 0
        for x1, y1, x2, y2 in chatting_pairs:
            if (x1 < horizontal_aisle <= x2) or (x2 < horizontal_aisle <= x1):
                separated_count += 1
            if (y1 < vertical_aisle <= y2) or (y2 < vertical_aisle <= y1):
                separated_count += 1
        return separated_count

    horizontal_impact = [0] * (M + 1)
    vertical_impact = [0] * (N + 1)

    for x1, y1, x2, y2 in chatting_pairs:
        if x1 != x2:
            min_row = min(x1, x2)
            horizontal_impact[min_row] += 1
        if y1 != y2:
            min_col = min(y1, y2)
            vertical_impact[min_col] += 1

    horizontal_impact.sort(reverse=True)
    vertical_impact.sort(reverse=True)

    best_horizontal_positions = []
    best_vertical_positions = []

    for i in range(K):
        best_horizontal_positions.append(horizontal_impact[i])
    for i in range(L):
        best_vertical_positions.append(vertical_impact[i])

    optimal_horizontal_aisles = sorted(range(1, M + 1), key=lambda x: horizontal_impact[x-1], reverse=True)[:K]
    optimal_vertical_aisles = sorted(range(1, N + 1), key=lambda y: vertical_impact[y-1], reverse=True)[:L]

    return (' '.join(map(str, optimal_horizontal_aisles)), ' '.join(map(str, optimal_vertical_aisles)))

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("The number of students must be positive and the number of passes must be non-negative.")

    # dp[i][j] will store the number of ways to reach student j after i passes
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1  # Starting point

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    return dp[m][0] % (10**9 + 7)

