def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(ciphertext_char, key_char):
        if ciphertext_char.isalpha():
            shift = ord(key_char.lower()) - ord('a')
            if ciphertext_char.islower():
                return chr((ord(ciphertext_char) - shift - ord('a')) % 26 + ord('a'))
            elif ciphertext_char.isupper():
                return chr((ord(ciphertext_char) - shift - ord('A')) % 26 + ord('A'))
        return ciphertext_char

    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]
    plaintext = ''

    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        plaintext += chr(value + 65) if ciphertext[i].isupper() else chr(value + 97)

    return plaintext.lower()

