def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Create a list to store the length of the longest increasing subsequence ending at each index
    lis = [1] * n
    # Create a list to store the length of the longest decreasing subsequence starting at each index
    lds = [1] * n

    # Fill lis array
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Fill lds array
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1

    # Find the maximum value of lis[i] + lds[i] - 1
    max_formation_length = 0
    for i in range(n):
        max_formation_length = max(max_formation_length, lis[i] + lds[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir formation length
    return n - max_formation_length

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1.")

    # Base case for 1 pair of discs
    if n == 1:
        return 2

    # Initialize the minimum moves for 1 pair
    moves = 2

    # Iteratively calculate the number of moves for each number of pairs up to n
    for i in range(2, n + 1):
        moves = 3 * moves + 2

    return moves
